/* Admin Theme font — must stay at CSS root (not nested under [data-wh-theme]). */

@font-face {
  font-family: "WebHemi Sans Serif";
  src: url("data:font/woff;base64,") format("woff");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
