  --wh-color-warning: #a16207;
  --wh-color-muted: #78716c;
  --wh-font-display: "Literata", "Georgia", serif;
  --wh-font-body: "Source Sans 3", "Segoe UI", sans-serif;
  --wh-radius-sm: 2px;
  --wh-radius-md: 6px;
  --wh-space-1: 0.25rem;
  --wh-space-2: 0.5rem;
  --wh-space-3: 0.75rem;
  --wh-space-4: 1rem;
  --wh-space-6: 1.5rem;
  --wh-space-8: 2rem;
}

/* Theme-owned document face (canvas stories only).
 * Skip when Storybook Docs is mounted — `.sbdocs` lives on the same body and
 * must keep Storybook’s own typography/layout (Introduction MDX, autodocs). */
[data-wh-theme="default"] body:not(:has(.sbdocs)) {
  margin: 0;
  font-family: var(--wh-font-body);
  color: var(--wh-color-ink);
  background: var(--wh-color-canvas);
  line-height: 1.5;
}
